import {mkdirSync,writeFileSync} from 'node:fs';
import {TRIANGLE_GRID,SEGMENT_DIGITS,INACTIVE_SEGMENTS} from '../shared/triangle-display.js';
import {pebbleColor} from '../shared/settings.js';
const directory='watchface/src/c/generated';mkdirSync(directory,{recursive:true});
writeFileSync(`${directory}/triangle_display.h`,[
  '// Generated by tools/generate-triangle-display.mjs. Exact equilateral geometry, sampled once.',
  '#include "palette_sizes.h"',
  `const uint16_t TRIANGLE_RUN_COUNT=${TRIANGLE_GRID.runs.length};`,
  `const uint8_t TRIANGLE_DIGIT_MASKS[10]={${SEGMENT_DIGITS.join(',')}};`,
  `const uint8_t TRIANGLE_INACTIVE[THEME_COUNT]={${INACTIVE_SEGMENTS.map(pebbleColor).join(',')}};`,
  'const TriangleRun TRIANGLE_RUNS[]={',
  ...TRIANGLE_GRID.runs.map(r=>`{${r.x},${r.y},${r.length},${r.group}},`),
  '};',''
].join('\n'));
console.log(`Triangular display: ${TRIANGLE_GRID.cells.length} cells, ${TRIANGLE_GRID.runs.length} pixel runs (${TRIANGLE_GRID.runs.length*4} bytes).`);
